<template>
    
    <div class="my-popups">
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">
                            {{ $t('Assign Group') }}
                        </h5>
                        <button v-on:click="CloseAssigngroup" type="button" class="close" data-original-title="Close">
                            <em class="fa fa-times"></em>
                        </button>
                    </div>
                    <div class="d-flex flex-wrap ml-4">
                        <div class="col-md-12 p-0 mt-4">
                            <div class="heading-border">
                                <h5 class="h5"><span>Assign Group To RFID TAG</span></h5>
                            </div>
                        </div>
                    </div>
                    <div class="modal-body">
                        <div class="border p-3">
                            <dynamic-form lang="en" ref="GroupItmes" :buttons="buttons" :schema="FormSchema" v-on:OnSubmit="onSubmit">
                            </dynamic-form>
                            <span class="mandatory">Fields marked with an asterisk (*) are mandatory.</span>
                        </div>                       
                    </div>
                   
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import { type } from 'jquery';
import DataService from '../../service/DataService';
export default {    
    props:{
        assDetailIDs:{
            tyep:Number,
            checkboxarray:Array
        },
        GroupId:{
            type:Number,
        }
    },
    data() {
        return {
            IsShowAddNamePopup: false,
            GroupData: [],
            TxtGroupName: '',
            group_name:'',
            selectedRFIDS:'',
            is_unassigned:'0',
            FormSchema: [
                {
                    layoutType: "double",
                    Data: [                        
                            {
                                astype: "SelectField",
                                label: this.$t('GroupName'),
                                name: "GroupName",
                                value: "",
                                placeholder: "",
                                validationRules:{"required":true},
                                config: {
                                    options: [],                                
                                },                                
                            }
                    ]
                }, 
                
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>"+this.$t('Save'),
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>"+this.$t('Cancel'),
                    onClick: this.CloseAssigngroup
                }
            ],
        }
    },
    created: function () {         
        this.GetGroupName();
        if((type(this.GroupId)!='undefined') && this.GroupId>0 ){
            this.FormSchema[0].Data[0].value=this.GroupId;
        }
        // this.GetScannedList();        
    },
    methods: {
        CloseAssigngroup: function () {           
            this.$emit('CloseScannedItem')
        },
        GetGroupName: async function () {            
        var vm = this;
          await DataService.GetScannedGroupName().then(response => {
                if (response.data != null) {                    
                    if (response.data.DATA.length > 0) {                       
                            vm.GroupData = response.data.DATA;
                                vm.GroupData.forEach((itm, index) => {                                 
                                    vm.FormSchema[0].Data[0].config.options.push({
                                    name: itm.group_name,
                                    value: itm.group_id,
                                });
                                vm.$refs.GroupItmes.UpdateKeyValue();
                        });
                    }
                }
            });
        },        
        onSubmit: async function (formfields) {    
            var vm = this;                 
           var obj=  `groupNames=${formfields.GroupName}&selectedRFIDS=${vm.assDetailIDs}&is_unassigned=${vm.is_unassigned}`;
            await  DataService.AddSaveAssignGroup(obj).then(response => {              
                if (response.data == 'True') {
                    vm.ShowAlert("Group Assgin successfully.", "success", true, vm.$t("Alert"));
                }
                this.$emit('CloseScannedItem')
                this.$emit('checkboxarray','')               
                this.$parent.GetScannedList();            
            });  
           
        },

    }
}
</script>